/* Private typedef -----------------------------------------------------------*/
typedef struct
{
  uint32_t identifier;                                                                                                  // 11-bit or 29-bit CAN identifier exactly as reported by the STM32 HAL
  uint32_t id_type;                                                                                                     // FDCAN_STANDARD_ID or FDCAN_EXTENDED_ID
  uint32_t data_length;                                                                                                 // STM32 HAL DLC encoding stored from FDCAN_RxHeaderTypeDef::DataLength
  uint32_t timestamp_ms;                                                                                                // HAL tick at which the frame was extracted from RX FIFO0
  uint8_t  data[8];                                                                                                     // Complete Classic-CAN payload; unused bytes remain zero
} CAN_RawFrame_t;

/* Private define ------------------------------------------------------------*/
#define CAN_RX_LOG_SIZE                       16U                                                                       // Number of raw frames retained per CAN controller for debugging/protocol identification

#define IMD_CAN_ID_INFO_GENERAL               0x037U                                                                    // Bender ISO175C DBC Standard ID: IMD_InfoGeneral
#define IMD_CAN_ID_INFO_ISOLATION_DETAIL      0x038U                                                                    // Bender ISO175C DBC Standard ID: IMD_InfoIsolationDetail
#define IMD_CAN_ID_INFO_VOLTAGE               0x039U                                                                    // Bender ISO175C DBC Standard ID: IMD_InfoVoltage
#define IMD_CAN_ID_INFO_IT_SYSTEM             0x03AU                                                                    // Bender ISO175C DBC Standard ID: IMD_InfoItSystem
#define IMD_GENERAL_MESSAGE_TIMEOUT_MS        500U                                                                      // Fail-safe timeout; set this above the configured IMD_InfoGeneral transmission period
#define IMD_DRIVE_DISABLE_PERIOD_MS           50U                                                                       // Period used to repeat Drive Enable = 0 while an IMD fault remains active

#define DTI_INVERTER_NODE_ID                  0x1BU                                                                     // DTI inverter Node ID used by the vehicle
#define DTI_PACKET_ID_DRIVE_ENABLE            0x0CU                                                                     // DTI CAN V2.4 packet ID for the Drive Enable command
#define DTI_CAN_ID_DRIVE_ENABLE               ((DTI_PACKET_ID_DRIVE_ENABLE << 8U) | DTI_INVERTER_NODE_ID)               // Extended DTI identifier: 0x0C1B for Node ID 0x1B

#define IMD_ALARM_DEVICE_ERROR                (1U << 0U)                                                                // Bender alarm bit 0: internal device error
#define IMD_ALARM_HV_POS_CONNECTION           (1U << 1U)                                                                // Bender alarm bit 1: HV positive connection error
#define IMD_ALARM_HV_NEG_CONNECTION           (1U << 2U)                                                                // Bender alarm bit 2: HV negative connection error
#define IMD_ALARM_EARTH_CONNECTION            (1U << 3U)                                                                // Bender alarm bit 3: earth connection error
#define IMD_ALARM_ISOLATION_ERROR             (1U << 4U)                                                                // Bender alarm bit 4: isolation below error threshold
#define IMD_ALARM_ISOLATION_WARNING           (1U << 5U)                                                                // Bender alarm bit 5: isolation below warning threshold
#define IMD_ALARM_ISOLATION_OUTDATED          (1U << 6U)                                                                // Bender alarm bit 6: isolation measurement exceeded its time limit
#define IMD_ALARM_UNBALANCE                   (1U << 7U)                                                                // Bender alarm bit 7: unbalance alarm
#define IMD_ALARM_UNDERVOLTAGE                (1U << 8U)                                                                // Bender alarm bit 8: undervoltage alarm
#define IMD_ALARM_UNSAFE_TO_START             (1U << 9U)                                                                // Bender alarm bit 9: unsafe-to-start condition
#define IMD_ALARM_EARTHLIFT                   (1U << 10U)                                                               // Bender alarm bit 10: earthlift opened
#define IMD_ALARM_SIGNAL_NOT_VALID            (1U << 15U)                                                               // Bender alarm bit 15: warning/alarm flags are not valid
#define IMD_ALARM_ACTIVE_MASK                 0x07FFU                                                                   // All defined active alarm/warning bits 0..10
#define IMD_ALARM_FAULT_MASK                  (IMD_ALARM_ACTIVE_MASK | IMD_ALARM_SIGNAL_NOT_VALID)                      // Every IMD alarm state that inhibits drive in this AMS implementation

#define IMD_R_ISO_STATUS_ESTIMATION           0U                                                                        // DBC value: isolation resistance is currently an estimation
#define IMD_R_ISO_STATUS_APPROXIMATION        1U                                                                        // DBC value: isolation resistance is currently an approximation
#define IMD_R_ISO_STATUS_NORMAL               2U                                                                        // DBC value: normal isolation measurement
#define IMD_R_ISO_STATUS_SNV                  3U                                                                        // DBC value: signal not valid

#define IMD_DEVICE_ACTIVITY_INITIALIZATION    0U                                                                        // DBC value: IMD initialization
#define IMD_DEVICE_ACTIVITY_NORMAL            1U                                                                        // DBC value: normal operation
#define IMD_DEVICE_ACTIVITY_SELFTEST          2U                                                                        // DBC value: self-test operation
#define IMD_DEVICE_ACTIVITY_SNV               255U                                                                      // DBC value: signal not valid

#define IMD_R_ISO_SNV_RAW                     0xFFFFU                                                                   // DBC raw value indicating that the isolation-resistance signal is not valid

#define IMD_FDCAN_HANDLE                      hfdcan2                                                                   // CAN interface physically assigned to the Standard-ID Bender IMD; change here if wiring is different
#define INVERTER_FDCAN_HANDLE                 hfdcan1                                                                   // Vehicle/inverter CAN interface used to transmit the DTI Extended-ID Drive Disable command

/* Private variables ---------------------------------------------------------*/
volatile CAN_RawFrame_t CAN1_rx_log[CAN_RX_LOG_SIZE] = {0};                                                             // Circular log containing the latest raw FDCAN1 frames
volatile CAN_RawFrame_t CAN2_rx_log[CAN_RX_LOG_SIZE] = {0};                                                             // Circular log containing the latest raw FDCAN2 frames
volatile uint32_t       CAN1_rx_count = 0U;                                                                             // Total number of data frames successfully extracted from FDCAN1 RX FIFO0
volatile uint32_t       CAN2_rx_count = 0U;                                                                             // Total number of data frames successfully extracted from FDCAN2 RX FIFO0
volatile uint32_t       CAN1_standard_count = 0U;                                                                       // Number of received FDCAN1 Standard-ID data frames
volatile uint32_t       CAN1_extended_count = 0U;                                                                       // Number of received FDCAN1 Extended-ID data frames
volatile uint32_t       CAN2_standard_count = 0U;                                                                       // Number of received FDCAN2 Standard-ID data frames
volatile uint32_t       CAN2_extended_count = 0U;                                                                       // Number of received FDCAN2 Extended-ID data frames
volatile bool           CAN_reception_error = false;                                                                    // Set when HAL cannot extract a frame that was present in RX FIFO0

volatile float          IMD_r_iso_corrected_kohm = 0.0f;                                                                // ID 0x37 bytes 0..1: corrected insulation resistance in kOhm
volatile uint8_t        IMD_r_iso_status = IMD_R_ISO_STATUS_SNV;                                                        // ID 0x37 bits 16..17: estimation/approximation/normal/SNV status
volatile uint8_t        IMD_isolation_counter = 0U;                                                                     // ID 0x37 byte 3: isolation measurement counter
volatile uint16_t       IMD_alarm_flags = IMD_ALARM_SIGNAL_NOT_VALID;                                                   // ID 0x37 bytes 4..5: complete warning/alarm bit field
volatile uint8_t        IMD_device_activity = IMD_DEVICE_ACTIVITY_SNV;                                                  // ID 0x37 byte 6: initialization/normal/self-test/SNV state

volatile bool           IMD_alarm_device_error = false;                                                                 // Decoded alarm bit 0
volatile bool           IMD_alarm_hv_pos_connection = false;                                                            // Decoded alarm bit 1
volatile bool           IMD_alarm_hv_neg_connection = false;                                                            // Decoded alarm bit 2
volatile bool           IMD_alarm_earth_connection = false;                                                             // Decoded alarm bit 3
volatile bool           IMD_alarm_isolation_error = false;                                                              // Decoded alarm bit 4
volatile bool           IMD_alarm_isolation_warning = false;                                                            // Decoded alarm bit 5
volatile bool           IMD_alarm_isolation_outdated = false;                                                           // Decoded alarm bit 6
volatile bool           IMD_alarm_unbalance = false;                                                                    // Decoded alarm bit 7
volatile bool           IMD_alarm_undervoltage = false;                                                                 // Decoded alarm bit 8
volatile bool           IMD_alarm_unsafe_to_start = false;                                                              // Decoded alarm bit 9
volatile bool           IMD_alarm_earthlift = false;                                                                    // Decoded alarm bit 10
volatile bool           IMD_alarm_signal_not_valid = true;                                                              // Decoded alarm bit 15; true means the alarm field itself is invalid

volatile float          IMD_r_iso_neg_kohm = 0.0f;                                                                      // ID 0x38 bytes 0..1: insulation resistance from HV- to earth
volatile float          IMD_r_iso_pos_kohm = 0.0f;                                                                      // ID 0x38 bytes 2..3: insulation resistance from HV+ to earth
volatile float          IMD_r_iso_original_kohm = 0.0f;                                                                 // ID 0x38 bytes 4..5: original non-corrected isolation resistance
volatile uint8_t        IMD_isolation_detail_counter = 0U;                                                              // ID 0x38 byte 6: detailed isolation measurement counter
volatile uint8_t        IMD_isolation_quality_percent = 0U;                                                             // ID 0x38 byte 7: isolation measurement quality in percent

volatile float          IMD_hv_voltage_v = 0.0f;                                                                        // ID 0x39 bytes 0..1: complete HV-system voltage
volatile float          IMD_hv_neg_to_earth_v = 0.0f;                                                                   // ID 0x39 bytes 2..3: HV- potential relative to earth
volatile float          IMD_hv_pos_to_earth_v = 0.0f;                                                                   // ID 0x39 bytes 4..5: HV+ potential relative to earth
volatile uint8_t        IMD_voltage_counter = 0U;                                                                       // ID 0x39 byte 6: voltage measurement counter

volatile float          IMD_capacity_uF = 0.0f;                                                                         // ID 0x3A bytes 0..1: measured IT-system capacity in microfarads
volatile uint8_t        IMD_capacity_counter = 0U;                                                                      // ID 0x3A byte 2: capacity measurement counter
volatile uint8_t        IMD_unbalance_percent = 0U;                                                                     // ID 0x3A byte 3: measured unbalance percentage
volatile uint8_t        IMD_unbalance_counter = 0U;                                                                     // ID 0x3A byte 4: unbalance measurement counter
volatile float          IMD_hv_frequency_hz = 0.0f;                                                                     // ID 0x3A bytes 5..6: measured HV frequency

volatile bool           IMD_info_general_received = false;                                                              // True after receiving one complete 0x37 Standard-ID frame
volatile bool           IMD_info_isolation_received = false;                                                            // True after receiving one complete 0x38 Standard-ID frame
volatile bool           IMD_info_voltage_received = false;                                                              // True after receiving one complete 0x39 Standard-ID frame
volatile bool           IMD_info_it_system_received = false;                                                            // True after receiving one complete 0x3A Standard-ID frame
volatile uint32_t       IMD_last_general_tick = 0U;                                                                     // Tick of the latest complete IMD_InfoGeneral frame
volatile uint32_t       IMD_last_isolation_tick = 0U;                                                                   // Tick of the latest complete IMD_InfoIsolationDetail frame
volatile uint32_t       IMD_last_voltage_tick = 0U;                                                                     // Tick of the latest complete IMD_InfoVoltage frame
volatile uint32_t       IMD_last_it_system_tick = 0U;                                                                   // Tick of the latest complete IMD_InfoItSystem frame

volatile bool           IMD_communication_timeout = true;                                                               // Fail-safe condition: no valid periodic general IMD status is currently available
volatile bool           IMD_measurement_invalid = true;                                                                 // True when R_iso status or corrected R_iso is SNV
volatile bool           IMD_device_not_normal = true;                                                                   // True while the IMD is not reporting normal operation
volatile bool           IMD_fault_active = true;                                                                        // Master safety flag; initialized true so drive is inhibited until a healthy IMD frame is received
volatile bool           IMD_drive_disable_tx_error = false;                                                             // Set when the AMS cannot queue the DTI Drive Disable frame
volatile uint32_t       IMD_drive_disable_tx_count = 0U;                                                                // Number of Drive Disable frames successfully queued because of IMD safety state

extern volatile float    AMS_battery_current;                                                                           // Physical battery current stored by main.c once the current-sensor protocol is known
extern volatile bool     AMS_current_valid;                                                                             // Indicates that AMS_battery_current contains a decoded current measurement
extern volatile uint32_t AMS_last_current_tick;                                                                         // Tick of the most recent valid current measurement

