/* CAN transmission ---------------------------------------------------------*/
HAL_StatusTypeDef can_send_frame(FDCAN_HandleTypeDef *hfdcan, uint32_t id, uint32_t id_type,
                                 const uint8_t *data, uint32_t data_length)                                             // Sends one Classic-CAN frame with caller-selected Standard or Extended ID
{
  if ((hfdcan == NULL) || (data == NULL))                                                                               // Reject invalid pointers before calling the HAL
  {
    return HAL_ERROR;                                                                                                   // Report invalid arguments to the caller
  }

  if ((id_type != FDCAN_STANDARD_ID) && (id_type != FDCAN_EXTENDED_ID))                                                 // Accept only the two Classic-CAN identifier formats
  {
    return HAL_ERROR;                                                                                                   // Reject unsupported identifier-type values
  }

  FDCAN_TxHeaderTypeDef header = {                                                                                      // Build the STM32 HAL transmit header for one Classic-CAN data frame
      .Identifier = id,                                                                                                 // Use the caller-provided 11-bit or 29-bit identifier
      .IdType = id_type,                                                                                                // Preserve Standard or Extended format selected by the caller
      .TxFrameType = FDCAN_DATA_FRAME,                                                                                  // Transmit a data frame rather than a remote frame
      .DataLength = data_length,                                                                                        // Use the STM32 HAL DLC constant provided by the caller
      .ErrorStateIndicator = FDCAN_ESI_ACTIVE,                                                                          // Report the controller as error active during normal operation
      .BitRateSwitch = FDCAN_BRS_OFF,                                                                                   // Classic CAN does not use CAN-FD bit-rate switching
      .FDFormat = FDCAN_CLASSIC_CAN,                                                                                    // Force Classic CAN rather than CAN FD
      .TxEventFifoControl = FDCAN_NO_TX_EVENTS,                                                                         // No transmit-event FIFO entry is required for these AMS messages
      .MessageMarker = 0U,                                                                                              // No application message marker is required
  };

  return HAL_FDCAN_AddMessageToTxFifoQ(hfdcan, &header, data);                                                          // Queue the prepared frame in the selected FDCAN transmit FIFO
}

static inline error can_send_raw(uint32_t id, const uint8_t *data,
                                 uint32_t raw_length)                                                                   // Legacy sender retained for existing BMS modules that call can_send()
{
  return ERROR_CAN_TX * (can_send_frame(&FDCAN_HANDLE, id, FDCAN_STANDARD_ID,
                                        data, raw_length) != HAL_OK);                                                   // Preserve the original Standard-ID behavior of can_send()
}

// NOLINTNEXTLINE (bugprone-easily-swappable-parameters)
error can_send(uint32_t const id, uint16_t const data)                                                                  // Legacy two-byte Standard-ID API retained for backward compatibility
{
  uint8_t data_bytes[2] = {                                                                                             // Explicit byte array avoids depending on MCU memory endianness
      (uint8_t)data,                                                                                                    // Original implementation sends the low byte first
      (uint8_t)(data >> 8U),                                                                                            // Original implementation sends the high byte second
  };

  return can_send_raw(id, data_bytes, FDCAN_DLC_BYTES_2);                                                               // Send the legacy two-byte frame through the configured BMS CAN handle
}
